export function ChatBackground() {
  return (
    <div
      className="pointer-events-none absolute inset-0 flex items-center justify-center overflow-hidden"
      aria-hidden
    >
      <svg
        viewBox="0 0 400 400"
        className="h-[min(70%,28rem)] w-[min(70%,28rem)] opacity-[0.14] text-primary"
        fill="none"
      >
        <circle
          cx="200"
          cy="200"
          r="120"
          stroke="currentColor"
          strokeWidth="1.5"
          strokeDasharray="6 8"
        />
        <circle
          cx="200"
          cy="200"
          r="80"
          stroke="currentColor"
          strokeWidth="1"
          strokeDasharray="4 6"
        />
        <circle
          cx="200"
          cy="200"
          r="40"
          stroke="currentColor"
          strokeWidth="1"
          strokeDasharray="3 5"
        />
        {[0, 60, 120, 180, 240, 300].map((deg) => {
          const rad = (deg * Math.PI) / 180;
          const x1 = 200 + Math.cos(rad) * 40;
          const y1 = 200 + Math.sin(rad) * 40;
          const x2 = 200 + Math.cos(rad) * 120;
          const y2 = 200 + Math.sin(rad) * 120;
          return (
            <line
              key={deg}
              x1={x1}
              y1={y1}
              x2={x2}
              y2={y2}
              stroke="currentColor"
              strokeWidth="1"
              strokeDasharray="4 6"
            />
          );
        })}
        {[0, 72, 144, 216, 288].map((deg) => {
          const rad = (deg * Math.PI) / 180;
          const x = 200 + Math.cos(rad) * 120;
          const y = 200 + Math.sin(rad) * 120;
          return (
            <circle
              key={`node-${deg}`}
              cx={x}
              cy={y}
              r="4"
              fill="currentColor"
            />
          );
        })}
        <circle cx="200" cy="200" r="6" fill="currentColor" />
      </svg>
    </div>
  );
}
