"use client";

import { useEffect, useState } from "react";
import { AppSidebar, type NavItem } from "@/components/app-sidebar";
import { ChatInterface } from "@/components/chat-interface";
import {
  Bookmark,
  MessageSquare,
  StickyNote,
  Zap,
} from "lucide-react";
import { cn } from "@/lib/utils";

const MEMORY_COUNT_KEY = "second-brain-memory-count";

const mobileNav: { id: NavItem; icon: typeof MessageSquare; label: string }[] =
  [
    { id: "chat", icon: MessageSquare, label: "Chat" },
    { id: "notes", icon: StickyNote, label: "Notes" },
    { id: "saved", icon: Bookmark, label: "Saved" },
    { id: "recall", icon: Zap, label: "Recall" },
  ];

export function AppShell() {
  const [activeNav, setActiveNav] = useState<NavItem>("chat");
  const [searchQuery, setSearchQuery] = useState("");
  const [memoryCount, setMemoryCount] = useState(0);

  useEffect(() => {
    const stored = sessionStorage.getItem(MEMORY_COUNT_KEY);
    if (stored) {
      const count = parseInt(stored, 10);
      if (!Number.isNaN(count) && count >= 0) {
        setMemoryCount(count);
      }
    }
  }, []);

  function handleMemoryCountChange(count: number) {
    setMemoryCount(count);
    sessionStorage.setItem(MEMORY_COUNT_KEY, String(count));
  }

  return (
    <div className="flex h-dvh min-h-dvh w-full flex-col overflow-hidden bg-background sm:flex-row">
      <nav
        className="flex shrink-0 items-center justify-around border-b border-border bg-sidebar px-2 py-2 sm:hidden"
        aria-label="Mobile navigation"
      >
        {mobileNav.map(({ id, icon: Icon, label }) => (
          <button
            key={id}
            type="button"
            onClick={() => setActiveNav(id)}
            className={cn(
              "flex flex-col items-center gap-0.5 rounded-xl px-3 py-1.5 text-[10px] font-medium",
              activeNav === id
                ? "bg-primary text-primary-foreground"
                : "text-primary",
            )}
          >
            <Icon className="size-4" />
            {label}
          </button>
        ))}
      </nav>

      <div className="hidden sm:flex sm:shrink-0">
        <AppSidebar
          activeNav={activeNav}
          onNavChange={setActiveNav}
          searchQuery={searchQuery}
          onSearchChange={setSearchQuery}
          memoryCount={memoryCount}
        />
      </div>

      <div className="flex min-h-0 min-w-0 flex-1 flex-col">
        <ChatInterface
          activeNav={activeNav}
          searchQuery={searchQuery}
          memoryCount={memoryCount}
          onMemoryCountChange={handleMemoryCountChange}
        />
      </div>
    </div>
  );
}
