"use client";

import {
  ArrowUp,
  FileText,
  Heart,
  Lightbulb,
  Loader2,
  MoreHorizontal,
  RefreshCw,
  Search,
  StickyNote,
  Zap,
} from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";
import type { NavItem } from "@/components/app-sidebar";
import { ChatBackground } from "@/components/chat-background";
import { ThemeToggle } from "@/components/theme-toggle";
import { VoiceMicButton } from "@/components/voice-mic-button";
import type { AskResponse, MemorySource, SaveMemoryResponse } from "@/lib/types";
import { cn } from "@/lib/utils";

const MAX_SAVE_LENGTH = 5000;
const MAX_ASK_LENGTH = 2000;
export type QuickAction = "note" | "idea" | "recall" | "search";

type ChatMessage = {
  id: string;
  role: "user" | "assistant";
  content: string;
  timestamp: Date;
  sources?: MemorySource[];
  kind?: "save" | "ask";
};

type ChatInterfaceProps = {
  activeNav: NavItem;
  searchQuery: string;
  onMemoryCountChange: (count: number) => void;
  memoryCount: number;
};

function formatTime(date: Date) {
  return date.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
}

function isSaveAction(action: QuickAction) {
  return action === "note" || action === "idea";
}

const quickActions: {
  id: QuickAction;
  label: string;
  icon: typeof StickyNote;
}[] = [
  { id: "note", label: "Note", icon: StickyNote },
  { id: "idea", label: "Idea", icon: Lightbulb },
  { id: "recall", label: "Recall", icon: Zap },
  { id: "search", label: "Search", icon: Search },
];

const welcomeMessages: ChatMessage[] = [
  {
    id: "welcome-1",
    role: "assistant",
    content:
      "Hi! I'm your Second Brain. Save notes and ideas, then ask me anything — I'll answer from what you've stored.",
    timestamp: new Date(),
  },
];

export function ChatInterface({
  activeNav,
  searchQuery,
  onMemoryCountChange,
  memoryCount,
}: ChatInterfaceProps) {
  const [messages, setMessages] = useState<ChatMessage[]>(welcomeMessages);
  const [text, setText] = useState("");
  const [quickAction, setQuickAction] = useState<QuickAction>("idea");
  const [isLoading, setIsLoading] = useState(false);
  const [expandedSources, setExpandedSources] = useState<Set<string>>(
    new Set(),
  );
  const [likedMessages, setLikedMessages] = useState<Set<string>>(new Set());
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  const isSaveMode = isSaveAction(quickAction);
  const maxLength = isSaveMode ? MAX_SAVE_LENGTH : MAX_ASK_LENGTH;

  useEffect(() => {
    if (activeNav === "notes") setQuickAction("note");
    if (activeNav === "recall") setQuickAction("recall");
  }, [activeNav]);

  const filteredMessages = useMemo(() => {
    let list = messages;

    if (activeNav === "saved") {
      list = list.filter((m) => m.kind === "save" || m.id.startsWith("welcome"));
    } else if (activeNav === "notes") {
      list = list.filter(
        (m) =>
          m.kind === "save" ||
          m.id.startsWith("welcome") ||
          m.role === "assistant",
      );
    } else if (activeNav === "recall") {
      list = list.filter(
        (m) =>
          m.kind === "ask" ||
          m.id.startsWith("welcome") ||
          (m.role === "assistant" && !m.kind),
      );
    }

    const q = searchQuery.trim().toLowerCase();
    if (!q) return list;

    return list.filter((m) => m.content.toLowerCase().includes(q));
  }, [messages, activeNav, searchQuery]);

  const scrollToBottom = useCallback(() => {
    requestAnimationFrame(() => {
      scrollRef.current?.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: "smooth",
      });
    });
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [filteredMessages.length, isLoading, scrollToBottom]);

  function appendTranscript(transcript: string) {
    setText((current) => {
      const trimmed = current.trim();
      const next = trimmed ? `${trimmed} ${transcript}` : transcript;
      return next.slice(0, maxLength);
    });
  }

  function toggleSources(messageId: string) {
    setExpandedSources((prev) => {
      const next = new Set(prev);
      if (next.has(messageId)) next.delete(messageId);
      else next.add(messageId);
      return next;
    });
  }

  function toggleLike(messageId: string) {
    setLikedMessages((prev) => {
      const next = new Set(prev);
      if (next.has(messageId)) next.delete(messageId);
      else next.add(messageId);
      return next;
    });
  }

  async function handleSave(content: string, userMessageId: string) {
    const response = await fetch("/api/memories", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ content }),
    });

    const data = (await response.json()) as SaveMemoryResponse & {
      error?: string;
    };

    if (!response.ok) {
      throw new Error(data.error ?? "Failed to save memory");
    }

    const prefix =
      quickAction === "idea" ? "Idea saved" : "Memory saved";
    const assistantMsg: ChatMessage = {
      id: `assistant-${Date.now()}`,
      role: "assistant",
      content: `${prefix} successfully. It's indexed and ready for recall.\n\nID: ${data.sourceId.slice(0, 8)}… · Status: ${data.status}`,
      timestamp: new Date(),
      kind: "save",
    };

    setMessages((prev) =>
      prev.map((m) =>
        m.id === userMessageId ? { ...m, kind: "save" as const } : m,
      ).concat(assistantMsg),
    );

    onMemoryCountChange(memoryCount + 1);
    toast.success("Memory saved");
  }

  async function handleAsk(question: string, userMessageId: string) {
    const response = await fetch("/api/ask", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ question }),
    });

    const data = (await response.json()) as AskResponse & { error?: string };

    if (!response.ok) {
      throw new Error(data.error ?? "Failed to get an answer");
    }

    const assistantMsg: ChatMessage = {
      id: `assistant-${Date.now()}`,
      role: "assistant",
      content: data.answer,
      timestamp: new Date(),
      sources: data.sources,
      kind: "ask",
    };

    setMessages((prev) =>
      prev
        .map((m) =>
          m.id === userMessageId ? { ...m, kind: "ask" as const } : m,
        )
        .concat(assistantMsg),
    );

    toast.success("Answer generated");
  }

  async function handleSend() {
    const trimmed = text.trim();
    if (!trimmed || isLoading) return;

    const userMessageId = `user-${Date.now()}`;
    const userMsg: ChatMessage = {
      id: userMessageId,
      role: "user",
      content: trimmed,
      timestamp: new Date(),
      kind: isSaveMode ? "save" : "ask",
    };

    setMessages((prev) => [...prev, userMsg]);
    setText("");
    setIsLoading(true);

    try {
      if (isSaveMode) {
        await handleSave(trimmed, userMessageId);
      } else {
        await handleAsk(trimmed, userMessageId);
      }
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Something went wrong";
      setMessages((prev) =>
        prev.concat({
          id: `error-${Date.now()}`,
          role: "assistant",
          content: message,
          timestamp: new Date(),
        }),
      );
      toast.error(message);
    } finally {
      setIsLoading(false);
    }
  }

  async function handleRegenerate(messageId: string) {
    const index = messages.findIndex((m) => m.id === messageId);
    if (index <= 0) return;

    const userMsg = messages[index - 1];
    if (userMsg?.role !== "user" || !userMsg.content) return;

    setIsLoading(true);
    try {
      if (userMsg.kind === "save") {
        await handleSave(userMsg.content, userMsg.id);
        setMessages((prev) => prev.filter((m) => m.id !== messageId));
      } else {
        await handleAsk(userMsg.content, userMsg.id);
        setMessages((prev) => prev.filter((m) => m.id !== messageId));
      }
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Something went wrong";
      toast.error(message);
    } finally {
      setIsLoading(false);
    }
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      void handleSend();
    }
  }

  const showEmptyNav =
    activeNav === "saved" &&
    !messages.some((m) => m.kind === "save") &&
    !searchQuery.trim();

  return (
    <div className="flex h-full min-h-0 flex-1 flex-col bg-cream">
      <header className="flex shrink-0 items-center justify-between gap-3 border-b border-border/50 bg-cream/80 px-4 py-3 backdrop-blur-sm sm:px-6">
        <div className="flex min-w-0 items-center gap-3">
          <div
            className="flex size-10 shrink-0 items-center justify-center rounded-full bg-primary text-sm font-bold text-primary-foreground"
            aria-hidden
          >
            SB
          </div>
          <div className="min-w-0">
            <h1 className="truncate text-base font-bold text-primary sm:text-lg">
              Second Brain
            </h1>
            <p className="flex items-center gap-1.5 text-xs text-muted-foreground">
              <span className="size-2 rounded-full bg-emerald-500" aria-hidden />
              Active Now
            </p>
          </div>
        </div>
        <div className="flex shrink-0 items-center gap-1">
          <ThemeToggle />
          <button
            type="button"
            className="flex size-9 items-center justify-center rounded-full border border-border/60 bg-card text-primary hover:bg-cream-dark"
            aria-label="More options"
          >
            <MoreHorizontal className="size-4" />
          </button>
        </div>
      </header>

      <div
        ref={scrollRef}
        className="relative min-h-0 flex-1 overflow-y-auto px-4 py-6 sm:px-8"
      >
        <ChatBackground />

        <div className="relative z-10 mx-auto flex max-w-3xl flex-col gap-5">
          {showEmptyNav ? (
            <p className="py-12 text-center text-sm text-muted-foreground">
              No saved notes yet. Use Note or Idea to save your first memory.
            </p>
          ) : (
            filteredMessages.map((message) => (
              <MessageBubble
                key={message.id}
                message={message}
                isLoading={isLoading}
                isLiked={likedMessages.has(message.id)}
                sourcesExpanded={expandedSources.has(message.id)}
                onToggleSources={() => toggleSources(message.id)}
                onToggleLike={() => toggleLike(message.id)}
                onRegenerate={() => void handleRegenerate(message.id)}
              />
            ))
          )}

          {isLoading ? (
            <div className="flex items-start gap-3">
              <Avatar label="SB" variant="assistant" />
              <div className="flex items-center gap-2 rounded-3xl border-2 border-primary/30 bg-card px-4 py-3">
                <Loader2 className="size-4 animate-spin text-primary" />
                <span className="text-sm text-muted-foreground">
                  {isSaveMode
                    ? "Saving and indexing your memory..."
                    : "Searching memories and generating answer..."}
                </span>
              </div>
            </div>
          ) : null}
        </div>
      </div>

      <div className="shrink-0 border-t border-border/50 bg-cream px-4 py-4 sm:px-6">
        <div className="mx-auto max-w-3xl space-y-3">
          <div className="flex flex-wrap gap-2">
            {quickActions.map(({ id, label, icon: Icon }) => (
              <button
                key={id}
                type="button"
                onClick={() => setQuickAction(id)}
                className={cn(
                  "inline-flex items-center gap-1.5 rounded-full px-4 py-2 text-sm font-medium transition-colors",
                  quickAction === id
                    ? "bg-primary text-primary-foreground shadow-sm"
                    : "border border-primary/30 bg-card text-primary hover:bg-cream-dark",
                )}
              >
                <Icon className="size-3.5" />
                {label}
              </button>
            ))}
          </div>

          <div className="flex items-end gap-2 rounded-3xl bg-chat-input px-3 py-2 shadow-md">
            <VoiceMicButton
              onTranscript={appendTranscript}
              disabled={isLoading}
            />
            <textarea
              ref={inputRef}
              value={text}
              onChange={(e) => setText(e.target.value.slice(0, maxLength))}
              onKeyDown={handleKeyDown}
              placeholder="Type your message here..."
              disabled={isLoading}
              rows={1}
              className="max-h-32 min-h-[2.5rem] min-w-0 flex-1 resize-none bg-transparent py-2.5 text-sm leading-relaxed text-chat-input-foreground placeholder:text-chat-input-foreground/50 focus:outline-none disabled:opacity-60"
              aria-label={
                isSaveMode ? "Memory text to save" : "Question to ask"
              }
            />
            <button
              type="button"
              onClick={() => void handleSend()}
              disabled={isLoading || !text.trim()}
              className="mb-1 flex size-9 shrink-0 items-center justify-center rounded-full text-chat-input-foreground/80 transition-colors hover:bg-white/10 disabled:opacity-40"
              aria-label="Send message"
            >
              <ArrowUp className="size-5" />
            </button>
          </div>

          <p className="text-center text-[10px] text-muted-foreground">
            {isSaveMode
              ? "Note & Idea save to HydraDB · Recall & Search ask your memories"
              : "Press Enter to send · Shift+Enter for new line"}
          </p>
        </div>
      </div>
    </div>
  );
}

function Avatar({
  label,
  variant,
}: {
  label: string;
  variant: "user" | "assistant";
}) {
  return (
    <div
      className={cn(
        "flex size-9 shrink-0 items-center justify-center rounded-full text-xs font-semibold",
        variant === "user"
          ? "bg-primary text-primary-foreground"
          : "border-2 border-primary bg-card text-primary",
      )}
      aria-hidden
    >
      {label}
    </div>
  );
}

function MessageBubble({
  message,
  isLoading,
  isLiked,
  sourcesExpanded,
  onToggleSources,
  onToggleLike,
  onRegenerate,
}: {
  message: ChatMessage;
  isLoading: boolean;
  isLiked: boolean;
  sourcesExpanded: boolean;
  onToggleSources: () => void;
  onToggleLike: () => void;
  onRegenerate: () => void;
}) {
  const isUser = message.role === "user";
  const sourceCount = message.sources?.length ?? 0;
  const isWelcome = message.id.startsWith("welcome");

  return (
    <div
      className={cn(
        "flex gap-3",
        isUser ? "flex-row-reverse" : "flex-row",
      )}
    >
      <Avatar label={isUser ? "You" : "SB"} variant={isUser ? "user" : "assistant"} />

      <div
        className={cn(
          "flex max-w-[min(100%,28rem)] flex-col gap-1.5",
          isUser ? "items-end" : "items-start",
        )}
      >
        <div
          className={cn(
            "rounded-3xl px-4 py-3 text-sm leading-relaxed shadow-sm",
            isUser
              ? "bg-primary text-primary-foreground"
              : "border-2 border-primary/40 bg-card text-primary",
          )}
        >
          <p className="whitespace-pre-wrap">{message.content}</p>

          {!isUser && sourceCount > 0 ? (
            <button
              type="button"
              onClick={onToggleSources}
              className="mt-2 flex items-center gap-1.5 text-xs font-medium text-primary/80 underline-offset-2 hover:underline"
            >
              <FileText className="size-3.5" />
              View sources ({sourceCount})
            </button>
          ) : null}
        </div>

        {sourcesExpanded && message.sources && message.sources.length > 0 ? (
          <div className="w-full max-w-md space-y-2 rounded-2xl border border-border/60 bg-card/90 p-3">
            {message.sources.map((source, index) => (
              <div
                key={`${source.sourceId}-${index}`}
                className="rounded-xl bg-cream-dark/80 p-3 text-xs"
              >
                <p className="font-medium text-primary">
                  Source {index + 1}
                  {source.title ? ` · ${source.title}` : ""}
                  {source.score != null
                    ? ` · ${Math.round(source.score * 100)}% match`
                    : ""}
                </p>
                <p className="mt-1 leading-relaxed text-muted-foreground">
                  {source.content || "No content available."}
                </p>
              </div>
            ))}
          </div>
        ) : null}

        {!isWelcome ? (
          <div
            className={cn(
              "flex items-center gap-2 text-[10px] text-muted-foreground",
              isUser && "flex-row-reverse",
            )}
          >
            <button
              type="button"
              onClick={onToggleLike}
              className={cn(
                "rounded-full p-1 transition-colors hover:text-primary",
                isLiked && "text-primary",
              )}
              aria-label={isLiked ? "Unlike message" : "Like message"}
            >
              <Heart
                className={cn("size-3.5", isLiked && "fill-current")}
              />
            </button>
            {!isUser && message.kind === "ask" ? (
              <button
                type="button"
                onClick={onRegenerate}
                disabled={isLoading}
                className="rounded-full p-1 transition-colors hover:text-primary disabled:opacity-40"
                aria-label="Regenerate answer"
              >
                <RefreshCw className="size-3.5" />
              </button>
            ) : null}
            <span>{formatTime(message.timestamp)}</span>
          </div>
        ) : null}
      </div>
    </div>
  );
}
